record Protein (n : ℕ) : Type where
  field
    sequence : Vec Char n
    coordinates : Vec (ℝ × ℝ × ℝ) n  
    confidence : Vec ℝ n
    confidence-bounds : ∀ i → 0r ≤ confidence i × confidence i ≤ 1r

