distance-sym : ∀ p₁ p₂ → distance p₁ p₂ ≡ distance p₂ p₁
distance-sym p₁ p₂ = refl

-- Non-negativity of distance
distance-pos : ∀ p₁ p₂ → 0r ≤ distance p₁ p₂  
distance-pos p₁ p₂ = sqrt-pos _

-- Triangle inequality
distance-triangle : ∀ p₁ p₂ p₃ → 
  distance p₁ p₃ ≤ distance p₁ p₂ + distance p₂ p₃
distance-triangle p₁ p₂ p₃ = {!!} -- Proof term

