                                  capture_output=True, text=True, timeout=60)

            if compile_result.returncode != 0:
                return {"status": "compile_error", "errors": compile_result.stderr}

            # Benchmark performance
            bench_result = sp.run(['futhark', 'bench', '--backend=opencl', fut_file], 
                                capture_output=True, text=True, timeout=120)

            return {
                "status": "success",
                "compile_output": compile_result.stdout,
                "benchmark": bench_result.stdout,
                "performance": self._parse_futhark_benchmark(bench_result.stdout)
            }

        except sp.TimeoutExpired:
            return {"status": "timeout", "message": "Futhark compilation timed out"}
        finally:
            os.unlink(fut_file)

