    }}

    // Copy results back
    cudaMemcpy(h_dist_matrix, d_dist_matrix, matrix_size, cudaMemcpyDeviceToHost);
    cudaMemcpy(h_energies, d_energies, float_size, cudaMemcpyDeviceToHost);

    // Calculate average energy for validation
    float avg_energy = 0.0f;
    for (int i = 0; i < n; i++) {{
        avg_energy += h_energies[i];
    }}
    avg_energy /= n;

