    cudaFree(d_forces);
    cudaFree(d_dist_matrix);
    cudaFree(d_energies);
    cudaFree(d_velocities);

    free(h_coords);
    free(h_dist_matrix);
    free(h_energies);

    return 0;
}}

int main() {{
    return cuda_predict_structure();
}}
