    def _parse_futhark_benchmark(self, output: str) -> Dict[str, float]:
        """Parse Futhark benchmark results"""
        metrics = {}
        lines = output.split('\n')
        for line in lines:
            if 'runtime:' in line.lower():
                try:
                    time_str = line.split(':')[1].strip()
                    if 'us' in time_str:
                        metrics['runtime_us'] = float(time_str.replace('us', ''))
                    elif 'ms' in time_str:
                        metrics['runtime_ms'] = float(time_str.replace('ms', ''))
                except:
                    pass
        return metrics

    def _parse_chapel_output(self, output: str) -> Dict[str, float]:
        """Parse Chapel execution metrics"""
        metrics = {}
        lines = output.split('\n')
        for line in lines:
            if 'seconds' in line:
                try:
                    time_val = float(line.split()[3])
                    metrics['execution_time'] = time_val
                except:
                    pass
            elif 'energy:' in line.lower():
                try:
                    energy_val = float(line.split(':')[1].strip())
                    metrics['final_energy'] = energy_val
                except:
                    pass
        return metrics

