        """Prolog knowledge-based structure analysis"""
        prolog_code = f"""
% AlphaFold 3++ Prolog Knowledge Base
% Protein structure analysis and prediction rules

% Amino acid properties
hydrophobic(ala). hydrophobic(val). hydrophobic(ile). hydrophobic(leu).
hydrophobic(met). hydrophobic(phe). hydrophobic(trp). hydrophobic(pro).

polar(ser). polar(thr). polar(asn). polar(gln). polar(tyr). polar(cys).

charged(asp). charged(glu). charged(lys). charged(arg). charged(his).

aromatic(phe). aromatic(trp). aromatic(tyr). aromatic(his).

% Secondary structure propensities
helix_former(ala). helix_former(glu). helix_former(leu). helix_former(met).
sheet_former(val). sheet_former(ile). sheet_former(phe). sheet_former(tyr).
turn_former(gly). turn_former(pro). turn_former(ser). turn_former(asp).

% Convert sequence to amino acid codes
sequence([{", ".join([f"'{aa.lower()}'" for aa in job.sequence])}]).

% Analyze amino acid composition
analyze_composition(Seq, hydrophobic(H), polar(P), charged(C)) :-
    findall(X, (member(X, Seq), hydrophobic(X)), HList),
    findall(X, (member(X, Seq), polar(X)), PList),  
    findall(X, (member(X, Seq), charged(X)), CList),
    length(HList, H),
    length(PList, P),
    length(CList, C).

% Predict secondary structure propensities
predict_helix_regions(Seq, HelixRegions) :-
    findall(I-AA, (nth1(I, Seq, AA), helix_former(AA)), HelixRegions).

predict_sheet_regions(Seq, SheetRegions) :-
    findall(I-AA, (nth1(I, Seq, AA), sheet_former(AA)), SheetRegions).

% Identify potential disulfide bonds
potential_disulfide(Seq, Bonds) :-
    findall(I, (nth1(I, Seq, cys)), CysPositions),
    findall(I-J, (member(I, CysPositions), member(J, CysPositions), I < J), Bonds).

% Stability prediction based on composition
stability(Seq, stable) :-
    analyze_composition(Seq, H, P, C),
    length(Seq, Len),
    HRatio is H / Len,
    PRatio is P / Len,
    HRatio > 0.3, PRatio > 0.2.

stability(Seq, unstable) :-
    \\+ stability(Seq, stable).

% Main prediction predicate
predict_structure(Seq, Result) :-
    analyze_composition(Seq, H, P, C),
    predict_helix_regions(Seq, HelixRegions),
    predict_sheet_regions(Seq, SheetRegions),
    potential_disulfide(Seq, Bonds),
    stability(Seq, StabilityLevel),
    length(Seq, Len),
    Result = [
