        hydrophobic_count(H),
        polar_count(P),
        charged_count(C),
        helix_regions(HelixRegions),
        sheet_regions(SheetRegions),
        disulfide_bonds(Bonds),
        stability(StabilityLevel)
    ].

% Query execution
:- sequence(Seq), predict_structure(Seq, Result), write(Result), nl, halt.
"""

        with tempfile.NamedTemporaryFile(mode='w', suffix='.pl', delete=False) as f:
