        hydrophobic => H,
        polar => P, 
        charged => C,
        hydrophobic_ratio => H / L,
        polar_ratio => P / L,
        charged_ratio => C / L
    }}.

% Secondary structure prediction
predict_secondary_structure(Seq) ->
    HelixFormers = "AELM",
    SheetFormers = "VIFY",

    Helix = [{{I, AA}} || {{I, AA}} <- lists:enumerate(Seq), 
                        lists:member(AA, HelixFormers)],
    Sheet = [{{I, AA}} || {{I, AA}} <- lists:enumerate(Seq),
                        lists:member(AA, SheetFormers)],

    #{{helix_positions => Helix, sheet_positions => Sheet}}.

% Concurrent distance matrix computation
compute_distances(Coords) ->
    N = length(Coords),
    Self = self(),

    % Spawn workers for parallel computation
    Workers = [spawn(fun() -> 
        distance_worker(Self, I, Coords) 
    end) || I <- lists:seq(1, N)],

    % Collect results
    collect_distances(Workers, []).

distance_worker(Parent, I, Coords) ->
    {{Xi, Yi, Zi}} = lists:nth(I, Coords),
    Distances = [begin
        {{Xj, Yj, Zj}} = lists:nth(J, Coords),
        Dx = Xi - Xj,
        Dy = Yi - Yj,
        Dz = Zi - Zj,
        math:sqrt(Dx*Dx + Dy*Dy + Dz*Dz)
    end || J <- lists:seq(1, length(Coords))],

    Parent ! {{distance_row, I, Distances}}.

collect_distances([], Acc) -> 
    lists:sort(Acc);
collect_distances(Workers, Acc) ->
    receive
        {{distance_row, I, Row}} ->
            collect_distances(Workers, [{{I, Row}} | Acc])
    after 1000 ->
        {{error, timeout}}
    end.

% Energy computation using actor model
compute_energy(Coords) ->
    N = length(Coords),
    Self = self(),

    % Spawn energy computation actors
    [spawn(fun() -> 
        energy_worker(Self, I, Coords) 
    end) || I <- lists:seq(1, N)],

    % Collect and sum energies
    TotalEnergy = collect_energies(N, 0),
    TotalEnergy / N.

energy_worker(Parent, I, Coords) ->
    {{Xi, Yi, Zi}} = lists:nth(I, Coords),
    Energy = lists:sum([begin
        if J =/= I ->
            {{Xj, Yj, Zj}} = lists:nth(J, Coords),
            Dx = Xi - Xj,
            Dy = Yi - Yj,
            Dz = Zi - Zj,
            R = math:sqrt(Dx*Dx + Dy*Dy + Dz*Dz),
            if R > 0 ->
                R6 = math:pow(R, 6),
                R12 = R6 * R6,
                4 * (1/R12 - 1/R6);
            true -> 0
            end;
        true -> 0
        end
    end || J <- lists:seq(1, length(Coords))]),

    Parent ! {{energy, I, Energy}}.

collect_energies(0, Sum) -> Sum;
collect_energies(N, Sum) ->
    receive
        {{energy, _I, Energy}} ->
            collect_energies(N-1, Sum + Energy)
    after 1000 ->
        Sum
    end.

